    def parse_synthetic_market_from_symbol(self, symbol: str, base: str = None, quote: str = None) -> Market:
        #
        # built locally(no HTTP); representative shape:
        # {
        #     "id": "ETH:*:ethereum:0xc02a…:0xa0b8…",
        #     "symbol": "0xc02a…/0xa0b8…@ETHnot *",
        #     "base": "WETH",
        #     "quote": "USDC",
        #     "baseId": "0xc02aa…",
        #     "quoteId": "0xa0b869…",
        #     "type": "spot",
        #     "spot": True,
        #     "active": True
        # }
        #
        parsed = self.ob_parse_dex_pair_symbol_input(symbol)
        tradingSymbol = self.safe_string(parsed, 'tradingSymbol')
        networkCode = self.safe_string(parsed, 'networkCode')
        dexCode = self.safe_string(parsed, 'dexCode')
        self.require_network_code(networkCode, symbol)
        self.assert_supported_dex_code(dexCode)
        parts = tradingSymbol.split('/')
        baseId = self.normalize_token_address(self.safe_string(parts, 0))
        quoteId = self.normalize_token_address(self.safe_string(parts, 1))
        return self.parse_synthetic_market(tradingSymbol, networkCode, dexCode, baseId, quoteId, base, quote)

    def index_address_pair_market_keys(self):
        marketsList = list(self.markets.values())
        for marketIndex in range(0, len(marketsList)):
            market = marketsList[marketIndex]
            unifiedSymbol = self.safe_string(market, 'symbol')
            if unifiedSymbol is None:
                continue
            if unifiedSymbol.find('@') < 0:
                continue
            parsed = self.ob_parse_network_dex_symbol(unifiedSymbol)
            networkCode = self.safe_string(parsed, 'networkCode')
            dexCode = self.safe_string(parsed, 'dexCode')
            effectiveDexCode = self.get_effective_dex_code(dexCode)
            baseId = self.safe_string(market, 'baseId')
            quoteId = self.safe_string(market, 'quoteId')
            base = self.safe_string(market, 'base')
            quote = self.safe_string(market, 'quote')
            if (baseId is not None) and (quoteId is not None):
                addressAliasSymbol = self.get_address_pair_symbol(baseId, quoteId, networkCode, dexCode)
                if (addressAliasSymbol != unifiedSymbol) and not (addressAliasSymbol in self.markets):
                    self.markets[addressAliasSymbol] = market
                if effectiveDexCode == '*':
                    tradingSymbol = self.safe_string(parsed, 'tradingSymbol')
                    if tradingSymbol is not None:
                        noDexTradingSymbolAlias = self.build_market_symbol(tradingSymbol, networkCode, None)
                        if (noDexTradingSymbolAlias != unifiedSymbol) and not (noDexTradingSymbolAlias in self.markets):
                            self.markets[noDexTradingSymbolAlias] = market
                        wildcardDexTradingSymbolAlias = self.build_market_symbol(tradingSymbol, networkCode, '*')
                        if (wildcardDexTradingSymbolAlias != unifiedSymbol) and not (wildcardDexTradingSymbolAlias in self.markets):
                            self.markets[wildcardDexTradingSymbolAlias] = market
                    noDexAddressAliasSymbol = self.get_address_pair_symbol(baseId, quoteId, networkCode, None)
                    if (noDexAddressAliasSymbol != unifiedSymbol) and not (noDexAddressAliasSymbol in self.markets):
                        self.markets[noDexAddressAliasSymbol] = market
                    wildcardDexAddressAliasSymbol = self.get_address_pair_symbol(baseId, quoteId, networkCode, '*')
                    if (wildcardDexAddressAliasSymbol != unifiedSymbol) and not (wildcardDexAddressAliasSymbol in self.markets):
                        self.markets[wildcardDexAddressAliasSymbol] = market
            if (base is not None) and (quote is not None) and self.is_address_pair_symbol(unifiedSymbol):
                tickerAliasSymbol = self.build_market_symbol(base + '/' + quote, networkCode, dexCode)
                if (tickerAliasSymbol != unifiedSymbol) and not (tickerAliasSymbol in self.markets):
                    self.markets[tickerAliasSymbol] = market
                if effectiveDexCode == '*':
                    noDexTickerAliasSymbol = self.build_market_symbol(base + '/' + quote, networkCode, None)
                    if (noDexTickerAliasSymbol != unifiedSymbol) and not (noDexTickerAliasSymbol in self.markets):
                        self.markets[noDexTickerAliasSymbol] = market
                    wildcardDexTickerAliasSymbol = self.build_market_symbol(base + '/' + quote, networkCode, '*')
                    if (wildcardDexTickerAliasSymbol != unifiedSymbol) and not (wildcardDexTickerAliasSymbol in self.markets):
                        self.markets[wildcardDexTickerAliasSymbol] = market
        unifiedSymbols: dict = {}
        for marketIndex in range(0, len(marketsList)):
            unifiedSymbol = self.safe_string(marketsList[marketIndex], 'symbol')
            if unifiedSymbol is not None:
                unifiedSymbols[unifiedSymbol] = True
        self.symbols = list(self.keysort(unifiedSymbols).keys())

    def set_markets(self, markets, currencies=None):
        super(defillama, self).set_markets(markets, currencies)
        self.index_address_pair_market_keys()
        return self.markets

    def merge_markets(self, newMarkets: List[Market]):
        existingMarkets = [] if (self.markets is None) else list(self.markets.values())
        combined = self.array_concat(existingMarkets, newMarkets)
        self.set_markets(combined)

    def is_market_symbol_cached(self, symbol: str) -> bool:
        if self.markets is None:
            return False
        normalizedSymbol = self.normalize_address_pair_symbol(symbol)
        return(symbol in self.markets) or ((normalizedSymbol != symbol) and (normalizedSymbol in self.markets))

    def remove_cached_market_symbol(self, symbol: str):
        if self.markets is None:
            return
        if symbol in self.markets:
            del self.markets[symbol]
        normalizedSymbol = self.normalize_address_pair_symbol(symbol)
        if (normalizedSymbol != symbol) and (normalizedSymbol in self.markets):
            del self.markets[normalizedSymbol]

    def ob_parse_dex_pair_symbol_input(self, symbol: str) -> dict:
        if symbol.find('@') >= 0:
            parsed = self.ob_parse_network_dex_symbol(symbol)
            dexCode = self.safe_string(parsed, 'dexCode')
            self.assert_supported_dex_code(dexCode)
            return parsed
        raise BadSymbol(self.id + ' symbol must include a network suffix using @ for ' + symbol)

    async def resolve_markets(self, symbols: List[str], params={}) -> dict:
        marketsBySymbol: dict = {}
        pendingSymbols = []
        marketsDict = {} if (self.markets is None) else self.markets
        for symbolIndex in range(0, len(symbols)):
            symbol = symbols[symbolIndex]
            normalizedSymbol = self.normalize_address_pair_symbol(symbol)
            if (symbol in marketsDict) or ((normalizedSymbol != symbol) and (normalizedSymbol in marketsDict)):
                marketsBySymbol[symbol] = self.market(symbol)
                continue
            pendingSymbols.append(symbol)
        newMarkets: List[Market] = []
        for pendingIndex in range(0, len(pendingSymbols)):
            symbol = pendingSymbols[pendingIndex]
            market = self.parse_synthetic_market_from_symbol(symbol)
            newMarkets.append(market)
            marketsBySymbol[symbol] = market
        if len(newMarkets) > 0:
            self.merge_markets(newMarkets)
            for pendingIndex in range(0, len(pendingSymbols)):
                symbol = pendingSymbols[pendingIndex]
                marketsBySymbol[symbol] = self.market(symbol)
        return {
            'marketsBySymbol': marketsBySymbol,
        }

    async def resolve_market(self, symbol: str, params={}) -> Market:
        resolveResult = await self.resolve_markets([symbol], params)
        return resolveResult['marketsBySymbol'][symbol]

    def build_coin_key(self, chainSlug: str, tokenAddress: str) -> str:
        return chainSlug + ':' + self.normalize_token_address(tokenAddress)

    def get_coin_keys_for_market(self, market: Market) -> List[str]:
        chainSlug = self.get_chain_slug_from_market(market)
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        keys: List[str] = []
        if (chainSlug is not None) and (baseId is not None):
            keys.append(self.build_coin_key(chainSlug, baseId))
        if (chainSlug is not None) and (quoteId is not None):
            keys.append(self.build_coin_key(chainSlug, quoteId))
        return keys

    def get_unique_coin_keys(self, coinKeys: List[str]) -> List[str]:
        uniqueKeys: dict = {}
        for keyIndex in range(0, len(coinKeys)):
            coinKey = coinKeys[keyIndex]
            if coinKey is not None:
                uniqueKeys[coinKey] = True
        return list(uniqueKeys.keys())

    def parse_coin_prices(self, response: dict) -> dict:
        #
        # GET /prices/current/{coins}
        # {
        #     "coins": {
        #         "ethereum:0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2": {
        #             "decimals": 18,
        #             "symbol": "WETH",
        #             "price": 1675.3099201762927,
        #             "timestamp": 1781423945,
        #             "confidence": 0.99
        #         },
        #         "ethereum:0xdAC17F958D2ee523a2206206994597C13D831ec7": {
        #             "decimals": 6,
        #             "symbol": "USDT",
        #             "price": 0.9994492627639542,
        #             "timestamp": 1781426524,
        #             "confidence": 0.99
        #         }
        #     }
        # }
        #
        return self.safe_dict(response, 'coins', {})

    async def fetch_current_prices(self, coinKeys: List[str], params={}) -> dict:
        uniqueKeys = self.get_unique_coin_keys(coinKeys)
        if len(uniqueKeys) == 0:
            return {}
        request: dict = {
            'coins': ','.join(uniqueKeys),
        }
        response = await self.publicGetPricesCurrentCoins(self.extend(request, params))
        return self.parse_coin_prices(response)

    def get_usd_price_from_coins(self, coins: dict, coinKey: str) -> float:
        entry = self.safe_dict(coins, coinKey)
        price = self.safe_number(entry, 'price')
        if price is None:
            raise BadSymbol(self.id + ' no USD price for coin ' + coinKey)
        return price

    def get_token_symbol_from_coins(self, coins: dict, coinKey: str) -> str:
        entry = self.safe_dict(coins, coinKey)
        return self.safe_currency_code(self.safe_string(entry, 'symbol'))

    def compute_pair_price(self, baseUsd: float, quoteUsd: float) -> float:
        if (baseUsd is None) or (quoteUsd is None) or (quoteUsd == 0):
            raise BadSymbol(self.id + ' cannot compute pair price from USD prices')
        return baseUsd / quoteUsd

    def enrich_market_from_coins(self, market: Market, coins: dict) -> Market:
        chainSlug = self.get_chain_slug_from_market(market)
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        baseKey = self.build_coin_key(chainSlug, baseId)
        quoteKey = self.build_coin_key(chainSlug, quoteId)
        baseSymbol = self.get_token_symbol_from_coins(coins, baseKey)
        quoteSymbol = self.get_token_symbol_from_coins(coins, quoteKey)
        if (baseSymbol is not None) and (baseSymbol != market['base']):
            market['base'] = baseSymbol
        if (quoteSymbol is not None) and (quoteSymbol != market['quote']):
            market['quote'] = quoteSymbol
        return market

    def parse_ticker_from_coins(self, market: Market, coins: dict, pairPrice: float) -> Ticker:
        #
        # last/close are derived: price_base_usd / price_quote_usd(not returned directly by API)
        # API has no volume fields; baseVolume and quoteVolume stay unset
        #
        symbol = self.safe_string(market, 'symbol')
        chainSlug = self.get_chain_slug_from_market(market)
        baseId = self.safe_string(market, 'baseId')
        baseKey = self.build_coin_key(chainSlug, baseId)
        baseEntry = self.safe_dict(coins, baseKey, {})
        timestamp = self.safe_integer(baseEntry, 'timestamp')
        last = self.number_to_string(pairPrice)
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp * 1000),
            'high': None,
            'low': None,
            'bid': last,
            'bidVolume': None,
            'ask': last,
            'askVolume': None,
            'vwap': None,
            'open': None,
            'close': last,
            'last': last,
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            'quoteVolume': None,
            'info': {
                'coins': coins,
                'pairPrice': pairPrice,
            },
        }, market)

    async def build_ticker_for_market(self, market: Market, coins: dict) -> Ticker:
        chainSlug = self.get_chain_slug_from_market(market)
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        baseKey = self.build_coin_key(chainSlug, baseId)
        quoteKey = self.build_coin_key(chainSlug, quoteId)
        baseUsd = self.get_usd_price_from_coins(coins, baseKey)
        quoteUsd = self.get_usd_price_from_coins(coins, quoteKey)
        pairPrice = self.compute_pair_price(baseUsd, quoteUsd)
        self.enrich_market_from_coins(market, coins)
        return self.parse_ticker_from_coins(market, coins, pairPrice)

    def collect_coin_keys_for_markets(self, marketsBySymbol: dict, symbols: List[str]) -> List[str]:
        allCoinKeys: List[str] = []
        for symbolIndex in range(0, len(symbols)):
            symbol = symbols[symbolIndex]
            market = self.safe_value(marketsBySymbol, symbol)
            marketCoinKeys = self.get_coin_keys_for_market(market)
            for keyIndex in range(0, len(marketCoinKeys)):
                allCoinKeys.append(marketCoinKeys[keyIndex])
        return allCoinKeys

    async def fetch_markets(self, params={}) -> List[Market]:
        """
        fetches markets; returns empty by default(markets loaded on demand)

        https://api-docs.defillama.com/#tag/coins

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Market[]: an array of market structures
        """
        return []

    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker for a market

        https://api-docs.defillama.com/#tag/coins/get/coins/prices/current/{coins}

        :param str symbol: unified market symbol with @network or @networknot * suffix
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        resolveResult = await self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        coinKeys = self.get_coin_keys_for_market(market)
        coins = await self.fetch_current_prices(coinKeys, params)
        ticker = await self.build_ticker_for_market(market, coins)
        ticker['symbol'] = symbol
        return ticker

    async def fetch_tickers(self, symbols: Strings = None, params={}) -> Tickers:
        """
        fetches price tickers for multiple markets; batches coin keys in one request

        https://api-docs.defillama.com/#tag/coins/get/coins/prices/current/{coins}

        :param str[] symbols: list of unified market symbols with @network or @networknot * suffix
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/?id=ticker-structure>`
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' fetchTickers() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' fetchTickers() requires a non-empty symbols argument')
        await self.load_markets()
        resolveResult = await self.resolve_markets(symbols, params)
        marketsBySymbol = resolveResult['marketsBySymbol']
        coinKeys = self.collect_coin_keys_for_markets(marketsBySymbol, symbols)
        coins = await self.fetch_current_prices(coinKeys, params)
        result: dict = {}
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            market = self.safe_value(marketsBySymbol, symbol)
            ticker = await self.build_ticker_for_market(market, coins)
            ticker['symbol'] = symbol
            result[symbol] = ticker
        return result

    async def ob_load_markets_for_symbols(self, symbols: List[str], reload=False, params={}) -> List[dict]:
        """
        lazily resolves and populates self.markets for the given symbols

        https://api-docs.defillama.com/#tag/coins

        :param str[] symbols: list of base/quote symbols with @network or @networknot * suffix
        :param boolean reload: when True, re-fetch symbols even if already cached in self.markets
        :param dict params: extra parameters specific to the exchange API endpoint
        :returns dict[]: empty list; ob_defillama returns fixed market status structures
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        await self.load_markets()
        symbolsToResolve = []
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            if reload:
                self.remove_cached_market_symbol(symbol)
                symbolsToResolve.append(symbol)
            elif not self.is_market_symbol_cached(symbol):
                symbolsToResolve.append(symbol)
        if len(symbolsToResolve) > 0:
            await self.resolve_markets(symbolsToResolve, params)
        return []

    def parse_pair_to_ob_dex_pair(self, market: Market, coins: dict, pairPrice: float) -> ObDexPair:
        #
        # {
        #     "symbol": "WETH/USDC",
        #     "network": "ETH",
        #     "dex": "*",
        #     "baseTokenAddress": "0xc02aa…",
        #     "quoteTokenAddress": "0xa0b869…",
        #     "price": 1675.31,
        #     "quoteLiquidity": 1
        # }
        #
        chainSlug = self.get_chain_slug_from_market(market)
        symbol = self.safe_string(market, 'symbol')
        parsed = self.ob_parse_network_dex_symbol(symbol)
        networkCode = self.safe_string(parsed, 'networkCode')
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        baseKey = self.build_coin_key(chainSlug, baseId)
        quoteKey = self.build_coin_key(chainSlug, quoteId)
        base = self.get_token_symbol_from_coins(coins, baseKey)
        quote = self.get_token_symbol_from_coins(coins, quoteKey)
        return {
            'symbol': base + '/' + quote,
            'network': networkCode,
            'dex': '*',
            'baseTokenAddress': baseId,
            'quoteTokenAddress': quoteId,
            'price': pairPrice,
            'quoteLiquidity': 1,
        }

    def build_venue_key(self, networkCode: str, dexCode: str) -> str:
        return networkCode + ':' + dexCode

    async def ob_fetch_dex_pairs(self, symbols: List[str], params={}) -> List[ObDexPair]:
        """
        returns DEX pair structures for DefiLlama(single venue per network, dex=*)

        https://api-docs.defillama.com/#tag/coins

        :param str[] symbols: list of symbols with @network or @networknot * suffix
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns ObDexPair[]: list of pair structures
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' obFetchDexPairs() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' obFetchDexPairs() requires a non-empty symbols argument')
        seenInputs: dict = {}
        parsedInputs: List[dict] = []
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            if symbol in seenInputs:
                continue
            seenInputs[symbol] = True
            parsedInputs.append(self.ob_parse_dex_pair_symbol_input(symbol))
        requiredTradingSymbols: dict = {}
        for inputIndex in range(0, len(parsedInputs)):
            parsedInput = parsedInputs[inputIndex]
            requiredTradingSymbols[parsedInput['tradingSymbol']] = True
        resolveSymbols = list(seenInputs.keys())
        await self.load_markets()
        resolveResult = await self.resolve_markets(resolveSymbols, params)
        marketsBySymbol = resolveResult['marketsBySymbol']
        coinKeys = self.collect_coin_keys_for_markets(marketsBySymbol, resolveSymbols)
        coins = await self.fetch_current_prices(coinKeys, params)
        venues: dict = {}
        for symbolIndex in range(0, len(resolveSymbols)):
            symbol = resolveSymbols[symbolIndex]
            parsedInput = self.ob_parse_dex_pair_symbol_input(symbol)
            tradingSymbol = parsedInput['tradingSymbol']
            networkCode = parsedInput['networkCode']
            market = self.safe_value(marketsBySymbol, symbol)
            if market is None:
                continue
            chainSlug = self.get_chain_slug_from_market(market)
            baseId = self.safe_string(market, 'baseId')
            quoteId = self.safe_string(market, 'quoteId')
            baseKey = self.build_coin_key(chainSlug, baseId)
            quoteKey = self.build_coin_key(chainSlug, quoteId)
            baseUsd = self.get_usd_price_from_coins(coins, baseKey)
            quoteUsd = self.get_usd_price_from_coins(coins, quoteKey)
            pairPrice = self.compute_pair_price(baseUsd, quoteUsd)
            venueKey = self.build_venue_key(networkCode, '*')
            if not (venueKey in venues):
                venues[venueKey] = {}
            venues[venueKey][tradingSymbol] = self.parse_pair_to_ob_dex_pair(market, coins, pairPrice)
        requiredSymbolsList = list(requiredTradingSymbols.keys())
        result = []
        venueKeys = list(venues.keys())
        for venueKeyIndex in range(0, len(venueKeys)):
            venueKey = venueKeys[venueKeyIndex]
            venueSymbols: dict = venues[venueKey]
            hasAllSymbols = True
            for requiredIndex in range(0, len(requiredSymbolsList)):
                requiredTradingSymbol = requiredSymbolsList[requiredIndex]
                if not (requiredTradingSymbol in venueSymbols):
                    hasAllSymbols = False
                    break
            if not hasAllSymbols:
                continue
            for requiredIndex in range(0, len(requiredSymbolsList)):
                requiredTradingSymbol = requiredSymbolsList[requiredIndex]
                result.append(venueSymbols[requiredTradingSymbol])
        return result

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        url = self.urls['api']['rest'] + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if response is None:
            return None
        if httpCode == 429:
            raise RateLimitExceeded(self.id + ' ' + body)
        return None
